package com.medicine.reminder.controller;
import com.medicine.reminder.model.*; import com.medicine.reminder.repository.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/profiles") public class UserController {private final ProfileRepository profiles;private final UserRepository users;public UserController(ProfileRepository p,UserRepository u){profiles=p;users=u;}private Long uid(Authentication a){return (Long)a.getDetails();}
 @GetMapping public List<UserProfile> list(Authentication a){return profiles.findByUserId(uid(a));}
 @PostMapping public UserProfile create(@RequestBody Map<String,String> d,Authentication a){UserProfile p=new UserProfile();p.setUser(users.findById(uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User not found")));copy(p,d);return profiles.save(p);}
 @PutMapping("/{id}") public UserProfile update(@PathVariable Long id,@RequestBody Map<String,String>d,Authentication a){UserProfile p=owned(id,uid(a));copy(p,d);return profiles.save(p);}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,Authentication a){profiles.delete(owned(id,uid(a)));}
 private UserProfile owned(Long id,Long u){return profiles.findByIdAndUserId(id,u).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Profile not found"));} private void copy(UserProfile p,Map<String,String>d){String n=d.getOrDefault("name","").trim();if(n.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name is required");p.setName(n);p.setRelation(d.getOrDefault("relation","Other"));p.setAvatar(d.getOrDefault("avatar","💊"));String ageStr=d.get("age");if(ageStr!=null&&!ageStr.isBlank()){try{p.setAge(Integer.parseInt(ageStr.trim()));}catch(Exception ignored){}}else{p.setAge(null);}p.setAllergies(d.getOrDefault("allergies",null));}}
